-- Digital SAT 연습 세트 2개 — 사용자 PC의 Practice Test Player(Rust/egui) 안에 있던 문항을 F2R로 옮겼다.
--   TP-SAT-MINI-02: 영어 미니 모의고사 21문항(읽기·쓰기 10 + 수학 11). Player의 "Make my own test" 템플릿은 이 세트와 같은 문항이라 따로 넣지 않는다.
--   TP-SAT-KO-01  : 한국어 미니 모의고사 21문항(읽기·쓰기 10 + 수학 11, 수학은 영어 세트를 한국어로 옮긴 것).
-- 원본 문항은 Player 제작 시 새로 쓴 연습 문항이다(College Board 문항 아님). Player의 2모듈 적응형 구성은 한 모듈로 이어 붙였다(1모듈 → 2모듈 → 어려운 2모듈 순).
-- 지문의 Text 1/Text 2 줄 머리와 2^(x+1) 표기만 F2R 본문 서식으로 바꿨고, 문항·선택지·정답은 원본 그대로다.
-- ko_help_json: 해설란(한글 해석·어휘·풀이·전략). 한국어 세트는 첫 칸을 '영어 원문'으로 둬서 SAT 영어 표현과 연결한다.
-- 모듈 시간은 화면이 문항 수로 계산한다(RW 10문항 12분, MATH 11문항 18분). 서버 마감은 7200초.
-- 스키마 변경 없음. exam_id는 exam_code로 회수한다.

INSERT INTO tp_exams (exam_code, kind, title, subtitle, description, difficulty, time_limit_sec, status, created_by) VALUES
('TP-SAT-MINI-02', 'SAT', 'Digital SAT Practice — Mini Set 02', 'Reading and Writing 10 questions (12 min) · Math 11 questions (18 min)', 'A short practice set with one Reading and Writing module and one Math module. Every question has a Korean help panel (translation, vocabulary, solution, strategy) that pauses the timer. Scores are F2R internal estimates, not official College Board SAT scores.', NULL, 7200, 'PUBLISHED', 'system'),
('TP-SAT-KO-01', 'SAT', '디지털 SAT 연습 — 한국어 미니 세트', '읽기·쓰기 10문항(12분) · 수학 11문항(18분)', 'SAT 형식에 익숙해지기 위한 한국어 연습 세트입니다. 해설란에서 영어 원문과 영어 표현, 풀이와 전략을 볼 수 있습니다. 점수는 F2R 내부 추정치이며 College Board 공식 SAT 점수가 아닙니다.', NULL, 7200, 'PUBLISHED', 'system');

SET @sat_mini02_exam_id = (SELECT exam_id FROM tp_exams WHERE exam_code = 'TP-SAT-MINI-02');
SET @sat_ko01_exam_id = (SELECT exam_id FROM tp_exams WHERE exam_code = 'TP-SAT-KO-01');

INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no, ko_help_json) VALUES
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice best states the main idea of the text?', 'Urban gardeners in the city of Larkfield noticed that tomato plants grown on rooftops produced fruit nearly two weeks earlier than plants grown at street level. A local botanist suggested that the extra warmth reflected from rooftop surfaces, rather than additional sunlight, was the main cause.', 'NONE', '["Rooftop tomatoes receive more sunlight than street-level tomatoes.", "Warmth from rooftop surfaces may explain why rooftop tomatoes ripen earlier.", "Botanists recommend growing all vegetables on rooftops.", "Street-level gardens in Larkfield produce no fruit."]', 'B', 1, 'The botanist attributes the earlier fruit to reflected warmth, not extra sunlight.', 1, '{"translation": "라크필드시의 도시 텃밭 농부들은 옥상에서 키운 토마토가 땅 높이에서 키운 토마토보다 거의 2주 일찍 열매를 맺는다는 것을 알아차렸다. 한 지역 식물학자는 추가로 받은 햇빛이 아니라 옥상 표면에서 반사된 여분의 열이 주된 원인이라고 보았다.\\n\\n질문: 글의 중심 생각으로 가장 알맞은 것은?\\n(A) 옥상 토마토는 땅 높이 토마토보다 햇빛을 더 받는다.\\n(B) 옥상 표면의 열이 옥상 토마토가 일찍 익는 이유일 수 있다.\\n(C) 식물학자들은 모든 채소를 옥상에서 키우라고 권한다.\\n(D) 라크필드의 땅 높이 텃밭에서는 열매가 열리지 않는다.", "vocab": [["urban", "도시의"], ["rooftop", "옥상"], ["street level", "땅(거리) 높이"], ["botanist", "식물학자"], ["reflect", "반사하다"], ["rather than", "~이 아니라"], ["main cause", "주된 원인"]], "solution": "정답 (B). 식물학자는 ''햇빛이 아니라(rather than additional sunlight) 반사된 열''을 원인으로 들었습니다. (A)는 글이 부정한 내용이고, (C)·(D)는 글에 없는 지나친 내용입니다.", "strategy": "【중심 생각】\\n1. 글을 읽고 ''누가/무엇이 → 어떻게 됐고 → 왜 그런가''를 한 줄로 요약하세요.\\n2. 의견이나 설명을 제시하는 사람(연구자·전문가)의 말이 핵심인 경우가 많습니다.\\n3. 글의 일부만 말하거나, 글에 없는 내용(권고·단정)을 덧붙인 선택지는 지웁니다.\\n4. 요약과 같은 방향의 선택지를 고르세요."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice completes the text with the most logical and precise word or phrase?', 'The violinist practiced the difficult passage slowly at first, then gradually increased her tempo. By the day of the concert, the notes that had once seemed ______ flowed from her bow with ease.', 'NONE', '["effortless", "daunting", "familiar", "brief"]', 'B', 1, 'The notes once seemed hard but later flowed with ease, so ''daunting'' fits the contrast.', 2, '{"translation": "그 바이올리니스트는 어려운 악절을 처음에는 천천히 연습한 뒤 점점 속도를 높였다. 연주회 날이 되자, 한때 ______해 보였던 음들이 그녀의 활에서 막힘없이 흘러나왔다.\\n\\n질문: 문맥상 가장 논리적이고 정확한 단어는?\\n(A) 수월한 (B) 벅찬(겁나는) (C) 익숙한 (D) 짧은", "vocab": [["passage (music)", "악절"], ["gradually", "점점"], ["tempo", "빠르기, 속도"], ["once seemed", "한때 ~해 보였던"], ["with ease", "쉽게, 막힘없이"], ["daunting", "벅찬, 겁나게 하는"]], "solution": "정답 (B) daunting. ''한때(once) ~해 보였던 음들이 이제는 쉽게(with ease) 흘러나왔다''는 대비이므로, 빈칸에는 ''쉽다''의 반대인 ''벅찬''이 들어가야 합니다. (A) effortless는 대비가 사라지고, (C)·(D)는 문맥과 맞지 않습니다.", "strategy": "【문맥 어휘】\\n1. 빈칸을 가린 채 앞뒤 문장만 보고 들어갈 말을 우리말로 먼저 떠올리세요.\\n2. ''once … but later'', '':'' 같은 대비·설명 신호를 찾아 빈칸 방향(긍정/부정, 반대/같음)을 정합니다.\\n3. 떠올린 말과 가장 가까운 선택지를 고르고, 반대 방향 선택지부터 지우세요."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Based on the texts, how would the author of Text 2 most likely respond to the historians in Text 1?', '**Text 1**
Some historians argue that the printing press spread new ideas mainly because it lowered the cost of books.

**Text 2**
Others point out that literacy rates rose only slowly, so cheaper books alone could not have reached most people; public readings and sermons carried printed ideas to listeners who could not read.', 'NONE', '["By agreeing that book prices were the only factor that mattered", "By arguing that spoken sharing of printed material also helped spread ideas", "By claiming that the printing press had no effect on ideas", "By stating that literacy rose quickly after printing began"]', 'B', 1, 'Text 2 adds that readings and sermons reached people who could not read.', 3, '{"translation": "【글 1】 일부 역사학자들은 인쇄기가 책값을 낮췄기 때문에 새로운 생각이 널리 퍼졌다고 주장한다.\\n【글 2】 다른 이들은 글을 읽을 줄 아는 사람이 천천히 늘었기 때문에 값싼 책만으로는 대부분의 사람에게 닿을 수 없었다고 지적한다. 공개 낭독과 설교가 글을 읽지 못하는 청중에게 인쇄된 생각을 전했다는 것이다.\\n\\n질문: 글 2의 필자는 글 1의 역사학자들에게 어떻게 반응하겠는가?\\n(A) 책값이 유일한 요인이었다고 동의한다.\\n(B) 인쇄물을 말로 나누는 방식도 생각을 퍼뜨리는 데 도움이 됐다고 주장한다.\\n(C) 인쇄기가 생각에 아무 영향도 주지 않았다고 주장한다.\\n(D) 인쇄가 시작된 뒤 문해율이 빠르게 올랐다고 말한다.", "vocab": [["printing press", "인쇄기"], ["lower the cost", "비용을 낮추다"], ["point out", "지적하다"], ["literacy rate", "문해율(글을 읽을 줄 아는 비율)"], ["public reading", "공개 낭독"], ["sermon", "설교"], ["listener", "청중, 듣는 사람"]], "solution": "정답 (B). 글 2는 책값만으로는 부족했고, 낭독과 설교처럼 ''말로 전하는 방식''이 글을 못 읽는 사람에게 생각을 전했다고 덧붙입니다. (A)는 ''유일한''이라 틀리고, (C)는 지나친 부정, (D)는 글 2의 ''천천히 늘었다''와 반대입니다.", "strategy": "【두 글 연결】\\n1. 글 1의 주장을 한 줄로 요약하세요.\\n2. 글 2가 그 주장에 대해 무엇을 더하거나 반박하는지 한 줄로 요약하세요.\\n3. ''전부 동의 / 일부 보완 / 전면 부정'' 중 어느 쪽인지 먼저 정합니다.\\n4. 글 2에 없는 지나친 주장(''전혀 영향 없음'', ''유일한 원인'')은 지웁니다."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which finding from the study is described in the text?', 'Marine biologist Ana Reyes tracked 40 sea turtles with satellite tags. She found that turtles hatched on the same beach often traveled to very different feeding grounds, yet nearly all of them returned to that beach to nest.', 'NONE', '["All turtles fed in the same place.", "Turtles rarely returned to their home beach.", "Turtles from one beach fed in different places but returned there to nest.", "Satellite tags changed where the turtles traveled."]', 'C', 1, 'The text says they spread out to feed but nearly all came back to nest.', 4, '{"translation": "해양생물학자 아나 레예스는 바다거북 40마리에 위성 추적 장치를 달아 추적했다. 그녀는 같은 해변에서 태어난 거북들이 서로 매우 다른 먹이터로 이동하는 경우가 많지만, 거의 모두가 알을 낳으러 그 해변으로 돌아온다는 것을 발견했다.\\n\\n질문: 글에 설명된 연구 결과는?\\n(A) 모든 거북이 같은 곳에서 먹이를 먹었다.\\n(B) 거북들은 태어난 해변으로 거의 돌아오지 않았다.\\n(C) 한 해변 출신 거북들은 서로 다른 곳에서 먹이를 먹었지만 알을 낳으러 그곳으로 돌아왔다.\\n(D) 위성 추적 장치가 거북의 이동 경로를 바꿨다.", "vocab": [["satellite tag", "위성 추적 장치"], ["hatch", "부화하다, 알에서 나오다"], ["feeding ground", "먹이터"], ["yet", "그런데도, 하지만"], ["nest (v.)", "둥지를 틀다, 알을 낳다"]], "solution": "정답 (C). 글은 ''서로 다른 먹이터로 갔다''와 ''거의 모두 같은 해변으로 돌아와 알을 낳았다'' 두 가지를 말합니다. 두 내용을 모두 담은 것은 (C)뿐입니다. (A)·(B)는 글과 반대이고 (D)는 글에 없습니다.", "strategy": "【세부 내용】\\n1. 질문이 묻는 대상(연구 결과, 원인 등)을 글에서 찾아 밑줄을 그으세요.\\n2. 정답은 글의 표현을 바꿔 말한 것입니다. 글과 뜻이 같은지 하나씩 대조하세요.\\n3. 글과 반대되거나 글에 없는 내용을 말하는 선택지는 지웁니다."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice completes the text with the most logical transition?', 'The committee''s report was praised for its clarity. ______, several members felt it left out important details about the budget.', 'NONE', '["Therefore", "Similarly", "However", "For example"]', 'C', 1, 'Praise followed by criticism is a contrast.', 5, '{"translation": "위원회의 보고서는 명확하다는 칭찬을 받았다. ______, 몇몇 위원은 그 보고서가 예산에 관한 중요한 세부 사항을 빠뜨렸다고 느꼈다.\\n\\n질문: 가장 논리적인 연결어는?\\n(A) Therefore(그러므로) (B) Similarly(마찬가지로) (C) However(그러나) (D) For example(예를 들어)", "vocab": [["committee", "위원회"], ["praise", "칭찬하다"], ["clarity", "명확성"], ["leave out", "빠뜨리다"], ["budget", "예산"]], "solution": "정답 (C) However. 앞 문장은 칭찬, 뒤 문장은 부족한 점에 대한 지적이므로 대조 관계입니다. 결과(A), 유사(B), 예시(D)는 이 관계에 맞지 않습니다.", "strategy": "【연결어】\\n1. 빈칸 앞 문장과 뒤 문장의 관계를 한 단어로 정하세요: 대조 / 결과 / 유사 / 예시.\\n2. 앞은 칭찬(긍정), 뒤는 지적(부정)처럼 방향이 바뀌는지 보세요.\\n3. 정한 관계에 맞는 연결어를 고르고 넣어 읽어 확인합니다."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice best describes the function of the text?', 'Researchers studying honeybees found that colonies exposed to a wider variety of flowers produced more honey and showed fewer signs of disease than colonies that fed mostly on one crop.', 'NONE', '["It reports a link between flower variety and colony health.", "It argues that honey production is declining.", "It explains how bees choose a single crop.", "It describes a method for treating bee diseases."]', 'A', 1, 'The text reports results connecting variety of flowers with honey and health.', 6, '{"translation": "꿀벌을 연구한 연구자들은 더 다양한 꽃을 접한 벌 무리가 주로 한 작물만 먹은 벌 무리보다 꿀을 더 많이 만들고 병의 징후도 더 적게 보인다는 것을 발견했다.\\n\\n질문: 글의 역할로 가장 알맞은 것은?\\n(A) 꽃의 다양성과 벌 무리의 건강 사이의 관련성을 보고한다.\\n(B) 꿀 생산량이 줄고 있다고 주장한다.\\n(C) 벌이 한 가지 작물을 고르는 방법을 설명한다.\\n(D) 벌의 병을 치료하는 방법을 설명한다.", "vocab": [["colony", "(벌의) 무리, 군집"], ["be exposed to", "~을 접하다, ~에 노출되다"], ["a wider variety of", "더 다양한"], ["signs of disease", "병의 징후"], ["crop", "작물"]], "solution": "정답 (A). 글은 연구 결과(꽃이 다양할수록 꿀이 많고 병이 적다)를 전달합니다. 글쓴이의 주장(B)이나 방법 설명(C·D)은 없습니다.", "strategy": "【글의 역할·목적】\\n1. 글이 무엇을 ''하는지'' 동사로 정리하세요: 보고한다 / 주장한다 / 설명한다 / 소개한다.\\n2. 연구 결과를 전달하기만 하는지, 자기 주장을 펴는지 구분합니다.\\n3. 글의 내용 범위를 벗어난 선택지(감소 주장, 치료 방법 등)는 지웁니다."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice completes the text with the most logical and precise word?', 'Many early maps were drawn from sailors'' descriptions rather than direct measurement. As a result, coastlines were often accurate in shape near busy ports but became ______ in remote regions.', 'NONE', '["precise", "distorted", "crowded", "decorated"]', 'B', 1, 'Away from ports, descriptions were scarce, so coastlines became distorted.', 7, '{"translation": "많은 옛 지도는 직접 측량하기보다 선원들의 설명을 바탕으로 그려졌다. 그 결과, 해안선은 붐비는 항구 근처에서는 모양이 정확한 경우가 많았지만 외딴 지역에서는 ______해졌다.\\n\\n질문: 문맥상 가장 논리적이고 정확한 단어는?\\n(A) 정확한 (B) 왜곡된 (C) 붐비는 (D) 장식된", "vocab": [["description", "설명, 묘사"], ["direct measurement", "직접 측량"], ["as a result", "그 결과"], ["coastline", "해안선"], ["remote", "외딴, 먼"], ["distorted", "왜곡된, 일그러진"]], "solution": "정답 (B) distorted. ''accurate … but became ______''로 대비되므로 ''정확하다''의 반대가 들어갑니다. 선원이 적은 먼 곳일수록 정보가 부족해 모양이 왜곡된 것입니다. (A)는 대비가 사라지고 (C)·(D)는 문맥과 무관합니다.", "strategy": "【문맥 어휘】\\n1. 빈칸을 가린 채 앞뒤 문장만 보고 들어갈 말을 우리말로 먼저 떠올리세요.\\n2. ''once … but later'', '':'' 같은 대비·설명 신호를 찾아 빈칸 방향(긍정/부정, 반대/같음)을 정합니다.\\n3. 떠올린 말과 가장 가까운 선택지를 고르고, 반대 방향 선택지부터 지우세요."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice best describes how the text characterizes the novel?', 'Although the novel''s plot is simple, its narrator''s shifting reliability invites readers to question every scene, turning a modest story into a puzzle.', 'NONE', '["Its plot is too complicated to follow.", "Its narrator makes a simple story feel complex.", "It lacks any memorable scenes.", "It was written mainly as a puzzle book."]', 'B', 1, 'The narrator''s unreliability turns a simple plot into a puzzle.', 8, '{"translation": "이 소설의 줄거리는 단순하지만, 믿을 만한지 계속 바뀌는 화자 때문에 독자는 모든 장면을 의심하게 되고, 평범한 이야기가 하나의 수수께끼가 된다.\\n\\n질문: 글은 소설을 어떻게 묘사하는가?\\n(A) 줄거리가 너무 복잡해서 따라가기 어렵다.\\n(B) 화자가 단순한 이야기를 복잡하게 느껴지게 만든다.\\n(C) 기억에 남는 장면이 없다.\\n(D) 주로 퍼즐 책으로 쓰였다.", "vocab": [["plot", "줄거리"], ["narrator", "화자(이야기하는 사람)"], ["reliability", "신뢰성"], ["shifting", "계속 바뀌는"], ["invite A to B", "A가 B하게 만들다"], ["modest", "평범한, 소박한"]], "solution": "정답 (B). ''Although 줄거리는 단순하다, 화자 때문에 수수께끼가 된다''에서 강조점은 뒤쪽입니다. (A)는 ''줄거리가 단순하다''와 반대이고, (C)·(D)는 글에 없습니다.", "strategy": "【글쓴이의 평가】\\n1. 평가 대상(소설)에 대해 글이 쓴 형용사·표현을 모두 표시하세요.\\n2. ''Although A, B'' 구조에서는 B가 글쓴이가 강조하는 내용입니다.\\n3. 표현을 그대로 옮기지 않았더라도 같은 뜻인 선택지를 고르세요."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'Which choice completes the text with the most logical and precise word?', 'The engineer''s proposal was ______: it addressed every concern the council had raised while staying within the original budget.', 'NONE', '["comprehensive", "tentative", "extravagant", "obscure"]', 'A', 1, 'Addressing every concern means it was comprehensive.', 9, '{"translation": "그 기술자의 제안은 ______했다. 위원회가 제기한 모든 우려를 다루면서도 원래 예산을 넘지 않았다.\\n\\n질문: 문맥상 가장 논리적이고 정확한 단어는?\\n(A) 포괄적인 (B) 잠정적인 (C) 사치스러운 (D) 모호한", "vocab": [["proposal", "제안"], ["address (v.)", "(문제를) 다루다"], ["concern", "우려, 걱정"], ["raise (a concern)", "(우려를) 제기하다"], ["comprehensive", "포괄적인, 빠짐없는"]], "solution": "정답 (A) comprehensive. 콜론 뒤에서 ''모든 우려를 다뤘다''고 했으므로 빠짐없다는 뜻의 ''포괄적인''이 맞습니다. ''예산 안에서''라는 말과 (C) 사치스러운은 반대이고, (B)·(D)는 근거가 없습니다.", "strategy": "【문맥 어휘】\\n1. 빈칸을 가린 채 앞뒤 문장만 보고 들어갈 말을 우리말로 먼저 떠올리세요.\\n2. ''once … but later'', '':'' 같은 대비·설명 신호를 찾아 빈칸 방향(긍정/부정, 반대/같음)을 정합니다.\\n3. 떠올린 말과 가장 가까운 선택지를 고르고, 반대 방향 선택지부터 지우세요."}'),
(@sat_mini02_exam_id, 'RW', 'SAT_RW_MC', 'According to the text, what caused the forests to thin?', 'Studies of ancient pollen in lake sediments show that forests in the region expanded rapidly after the last ice age, then thinned again as early farmers cleared land.', 'NONE', '["A return of colder weather", "Changes in lake levels", "Land clearing by early farmers", "Loss of pollen-producing trees to disease"]', 'C', 1, 'The text names farmers clearing land.', 10, '{"translation": "호수 퇴적물 속 옛 꽃가루를 연구한 결과, 이 지역의 숲은 마지막 빙하기 이후 빠르게 넓어졌다가 초기 농민들이 땅을 개간하면서 다시 줄어들었다.\\n\\n질문: 글에 따르면 숲이 줄어든 원인은?\\n(A) 추운 날씨가 다시 찾아와서\\n(B) 호수 수위가 바뀌어서\\n(C) 초기 농민들이 땅을 개간해서\\n(D) 꽃가루를 만드는 나무가 병으로 죽어서", "vocab": [["pollen", "꽃가루"], ["sediment", "퇴적물"], ["ice age", "빙하기"], ["thin (v.)", "(숲이) 줄어들다, 듬성해지다"], ["clear land", "땅을 개간하다(나무를 베어 내다)"]], "solution": "정답 (C). ''thinned again as early farmers cleared land''에서 as가 원인을 알려 줍니다. (A)·(B)·(D)는 글에 나오지 않습니다.", "strategy": "【원인 찾기】\\n1. 질문의 결과(숲이 줄어듦)가 글의 어디에 나오는지 찾으세요.\\n2. 그 바로 앞뒤의 ''as'', ''because'', ''after'' 같은 원인 표현을 확인합니다.\\n3. 글에 나오지 않은 원인(날씨, 질병)은 그럴듯해도 지웁니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_MC', 'If 3x + 7 = 22, what is the value of x?', NULL, 'NONE', '["3", "5", "7", "15"]', 'B', 1, 'Subtract 7 to get 3x = 15, then divide by 3.', 11, '{"translation": "3x + 7 = 22일 때, x의 값은?", "vocab": [["value", "값"], ["equation", "방정식"]], "solution": "정답 (B) 5. 양변에서 7을 빼면 3x = 15, 3으로 나누면 x = 5입니다. 확인: 3(5) + 7 = 22.", "strategy": "【일차방정식】\\n1. 숫자 항을 반대편으로 옮기고(덧셈↔뺄셈), x의 계수로 나누세요.\\n2. 구한 값을 원래 식에 넣어 확인하면 부호 실수를 막을 수 있습니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_MC', 'A line passes through (0, 2) and (4, 10). What is its slope?', NULL, 'NONE', '["1/2", "2", "4", "8"]', 'B', 1, '(10 − 2) / (4 − 0) = 8 / 4 = 2.', 12, '{"translation": "직선이 점 (0, 2)와 (4, 10)을 지난다. 이 직선의 기울기는?", "vocab": [["line", "직선"], ["pass through", "~을 지나다"], ["slope", "기울기"]], "solution": "정답 (B) 2. 기울기 = (10 − 2) ÷ (4 − 0) = 8 ÷ 4 = 2입니다. (A) 1/2은 분자·분모를 뒤집은 값입니다.", "strategy": "【기울기】\\n1. 기울기 = (y의 변화량) ÷ (x의 변화량)입니다.\\n2. 두 점의 순서를 분자와 분모에서 똑같이 맞추세요.\\n3. 1/2처럼 분자·분모를 뒤집은 선택지가 흔한 함정입니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_SPR', 'A rectangle has a length of 12 and a width of 5. What is the length of its diagonal?', NULL, 'NONE', NULL, '13', 1, '√(12² + 5²) = √169 = 13.', 13, '{"translation": "가로가 12, 세로가 5인 직사각형의 대각선 길이는?", "vocab": [["rectangle", "직사각형"], ["length / width", "가로(길이) / 세로(폭)"], ["diagonal", "대각선"]], "solution": "정답 13. 대각선² = 12² + 5² = 144 + 25 = 169이므로 대각선 = 13입니다.", "strategy": "【피타고라스 정리 · 직접 입력】\\n1. 직사각형의 대각선은 가로·세로를 두 변으로 하는 직각삼각형의 빗변입니다.\\n2. 공식표의 c² = a² + b²를 쓰세요. 5, 12, 13처럼 자주 나오는 세 수를 기억해 두면 빠릅니다.\\n3. 답은 숫자만 입력합니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_SPR', 'What is the value of 7/4 written as a decimal or fraction?', NULL, 'NONE', NULL, '1.75|7/4', 1, '7 ÷ 4 = 1.75.', 14, '{"translation": "7/4를 소수 또는 분수로 나타낸 값은?", "vocab": [["decimal", "소수"], ["fraction", "분수"], ["written as", "~로 나타낸"]], "solution": "정답 1.75 (또는 7/4). 7 ÷ 4 = 1.75입니다. 두 꼴 모두 정답입니다.", "strategy": "【분수 ↔ 소수 · 직접 입력】\\n1. 분수는 분자 ÷ 분모로 소수가 됩니다.\\n2. 이 문항은 분수 그대로 넣어도, 소수로 넣어도 정답입니다.\\n3. 대분수(1 3/4)는 입력할 수 없습니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_MC', 'What is 15% of 80?', NULL, 'NONE', '["8", "10", "12", "15"]', 'C', 1, '0.15 × 80 = 12.', 15, '{"translation": "80의 15%는?", "vocab": [["percent (%)", "퍼센트"], ["of", "~의"]], "solution": "정답 (C) 12. 80 × 0.15 = 12입니다(10%는 8, 5%는 4, 합 12).", "strategy": "【백분율】\\n1. a%는 a/100입니다. ''80의 15%''는 80 × 0.15입니다.\\n2. 10%(8)와 5%(4)로 나눠 더하면 암산이 쉽습니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_MC', 'Which expression is equivalent to (x + 3)(x − 3)?', NULL, 'NONE', '["x² − 9", "x² + 9", "x² − 6x + 9", "x² + 6x − 9"]', 'A', 1, 'Difference of squares: x² − 3².', 16, '{"translation": "(x + 3)(x − 3)과 같은 식은?", "vocab": [["expression", "식"], ["equivalent to", "~과 같은(동치인)"]], "solution": "정답 (A) x² − 9. 합차 공식 (a + b)(a − b) = a² − b²에 따라 x² − 3² = x² − 9입니다.", "strategy": "【합차 공식】\\n1. (a + b)(a − b) = a² − b²를 떠올리세요.\\n2. 가운데 항(±6x)이 생기는 것은 (x ± 3)²처럼 같은 부호를 곱할 때뿐입니다.\\n3. 헷갈리면 x = 1을 넣어 원래 식과 선택지 값을 비교하세요."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_SPR', 'If f(x) = 2x² − 1, what is f(3)?', NULL, 'NONE', NULL, '17', 1, '2 · 9 − 1 = 17.', 17, '{"translation": "f(x) = 2x² − 1일 때, f(3)의 값은?", "vocab": [["function", "함수"], ["f(3)", "x = 3일 때의 함숫값"]], "solution": "정답 17. f(3) = 2 × 3² − 1 = 2 × 9 − 1 = 17입니다.", "strategy": "【함숫값 · 직접 입력】\\n1. f(3)은 x 자리에 3을 넣으라는 뜻입니다.\\n2. 거듭제곱을 먼저 계산하고(3² = 9) 곱셈, 뺄셈 순서로 계산하세요."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_MC', 'The system y = 2x + 1 and y = −x + 7 has one solution (x, y). What is x?', NULL, 'NONE', '["1", "2", "3", "5"]', 'B', 1, '2x + 1 = −x + 7 gives 3x = 6, so x = 2.', 18, '{"translation": "연립방정식 y = 2x + 1과 y = −x + 7은 해 (x, y)를 하나 가진다. x의 값은?", "vocab": [["system (of equations)", "연립방정식"], ["solution", "해"]], "solution": "정답 (B) 2. 2x + 1 = −x + 7에서 3x = 6, x = 2입니다(이때 y = 5).", "strategy": "【연립방정식】\\n1. 두 식이 모두 y = … 꼴이면 오른쪽끼리 같다고 놓으세요.\\n2. x를 구한 뒤 묻는 것이 x인지 y인지 다시 확인하세요.\\n3. 계산기 그래프에 두 식을 넣고 만나는 점을 봐도 됩니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_SPR', 'A circle has the equation (x − 2)² + (y + 1)² = 49. What is its radius?', NULL, 'NONE', NULL, '7', 1, 'The right side is r², so r = 7.', 19, '{"translation": "원의 방정식이 (x − 2)² + (y + 1)² = 49일 때, 반지름은?", "vocab": [["circle", "원"], ["radius", "반지름"], ["center", "중심"]], "solution": "정답 7. 오른쪽 49가 r²이므로 r = 7입니다. 중심은 (2, −1)입니다.", "strategy": "【원의 방정식 · 직접 입력】\\n1. (x − a)² + (y − b)² = r²에서 중심은 (a, b), 반지름은 r입니다.\\n2. 오른쪽 수는 r²이므로 제곱근을 구해야 합니다. 그 수를 그대로 답으로 쓰는 실수가 흔합니다."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_MC', 'If 2^{x+1} = 32, what is x?', NULL, 'NONE', '["3", "4", "5", "6"]', 'B', 1, '32 = 2⁵, so x + 1 = 5 and x = 4.', 20, '{"translation": "2^(x+1) = 32일 때, x의 값은?", "vocab": [["exponent", "지수"], ["power of 2", "2의 거듭제곱"]], "solution": "정답 (B) 4. 32 = 2⁵이므로 x + 1 = 5, x = 4입니다. (C) 5는 x + 1의 값입니다.", "strategy": "【지수 방정식】\\n1. 양변을 같은 밑(2)의 거듭제곱으로 바꾸세요.\\n2. 밑이 같으면 지수끼리 같다고 놓고 풉니다.\\n3. 지수 자리의 식(x + 1)을 x로 착각하지 마세요."}'),
(@sat_mini02_exam_id, 'MATH', 'SAT_MATH_SPR', 'The mean of five numbers is 12. Four of them are 10, 11, 13 and 14. What is the fifth?', NULL, 'NONE', NULL, '12', 1, 'Total is 60; 60 − 48 = 12.', 21, '{"translation": "다섯 수의 평균이 12이다. 그중 네 수가 10, 11, 13, 14일 때 다섯째 수는?", "vocab": [["mean", "평균"], ["the fifth (number)", "다섯째 수"]], "solution": "정답 12. 전체 합 = 12 × 5 = 60, 네 수의 합 = 48이므로 60 − 48 = 12입니다.", "strategy": "【평균 · 직접 입력】\\n1. 평균 × 개수 = 전체 합입니다.\\n2. 전체 합에서 아는 수들의 합을 빼면 나머지 수가 나옵니다."}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '이 글의 중심 내용으로 가장 알맞은 것은?', '한 마을의 도서관은 저녁 운영 시간을 두 시간 늘린 뒤 방문객이 크게 늘었다. 사서는 새로 온 방문객 대부분이 낮에 일하는 직장인이라는 점에 주목했다.', 'NONE', '["도서관은 낮 시간 운영을 줄였다.", "운영 시간을 늘리자 낮에 일하는 사람들이 더 많이 찾아왔다.", "사서는 직장인이 책을 읽지 않는다고 생각했다.", "마을 사람들은 도서관을 좋아하지 않는다."]', 'B', 1, '저녁 시간을 늘린 뒤 직장인 방문객이 늘었다는 내용이다.', 1, '{"translation": "A town library extended its evening hours by two hours, and the number of visitors rose sharply. The librarian noted that most of the new visitors were people who work during the day.\\n\\nQuestion: Which choice best states the main idea of the text?", "vocab": [["중심 내용", "main idea"], ["운영 시간을 늘리다", "extend the hours"], ["방문객", "visitor"], ["사서", "librarian"], ["주목하다", "note"], ["직장인", "office worker / people who work during the day"]], "solution": "정답 (B). 저녁 운영 시간을 늘리자 방문객이 늘었고, 새 방문객 대부분이 낮에 일하는 사람이었다는 두 사실을 묶은 선택지입니다. (A)는 글에 없고, (C)·(D)는 글과 맞지 않습니다.", "strategy": "【중심 생각】\\n1. 글을 읽고 ''누가/무엇이 → 어떻게 됐고 → 왜 그런가''를 한 줄로 요약하세요.\\n2. 의견이나 설명을 제시하는 사람(연구자·전문가)의 말이 핵심인 경우가 많습니다.\\n3. 글의 일부만 말하거나, 글에 없는 내용(권고·단정)을 덧붙인 선택지는 지웁니다.\\n4. 요약과 같은 방향의 선택지를 고르세요.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '빈칸에 들어갈 말로 가장 알맞은 것은?', '그는 처음 무대에 섰을 때 몹시 떨었지만, 공연을 거듭할수록 점점 ______ 모습을 보였다.', 'NONE', '["불안한", "여유로운", "지친", "어색한"]', 'B', 1, '처음에는 떨었지만 점점 나아졌다는 대비이므로 ''여유로운''이 알맞다.', 2, '{"translation": "He trembled badly the first time he stood on stage, but with each performance he appeared more and more ______.\\n\\nQuestion: Which choice completes the text with the most logical and precise word?", "vocab": [["빈칸", "blank"], ["떨다", "tremble"], ["무대", "stage"], ["공연을 거듭할수록", "with each performance"], ["여유로운", "relaxed, at ease"]], "solution": "정답 (B) 여유로운. ''처음에는 몹시 떨었지만(but) 공연을 거듭할수록 점점''이라는 대비가 있으므로 떨림의 반대인 ''여유로운''이 알맞습니다. (A)·(D)는 대비가 사라지고 (C)는 근거가 없습니다.", "strategy": "【문맥 어휘】\\n1. 빈칸을 가린 채 앞뒤 문장만 보고 들어갈 말을 우리말로 먼저 떠올리세요.\\n2. ''once … but later'', '':'' 같은 대비·설명 신호를 찾아 빈칸 방향(긍정/부정, 반대/같음)을 정합니다.\\n3. 떠올린 말과 가장 가까운 선택지를 고르고, 반대 방향 선택지부터 지우세요.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '글 2의 필자는 글 1의 주장에 대해 어떻게 반응하겠는가?', '**글 1**
어떤 학자들은 인쇄술이 책값을 낮춰 지식을 널리 퍼뜨렸다고 본다.

**글 2**
다른 학자들은 글을 읽을 줄 아는 사람이 적었으므로, 책을 소리 내어 읽어 주는 모임이 지식을 전하는 데 큰 역할을 했다고 본다.', 'NONE', '["책값만이 유일한 원인이었다고 동의한다.", "읽어 주는 모임처럼 말로 전하는 방식도 중요했다고 덧붙인다.", "인쇄술은 아무 영향도 없었다고 주장한다.", "글을 읽는 사람이 빠르게 늘었다고 말한다."]', 'B', 1, '글 2는 글을 못 읽는 사람에게 말로 전해진 경로를 덧붙인다.', 3, '{"translation": "Text 1: Some scholars believe printing spread knowledge widely by lowering the price of books.\\nText 2: Other scholars believe that, because few people could read, gatherings where books were read aloud played a major role in passing on knowledge.\\n\\nQuestion: How would the author of Text 2 most likely respond to the claim in Text 1?", "vocab": [["글 1 / 글 2", "Text 1 / Text 2"], ["인쇄술", "printing"], ["책값", "price of books"], ["소리 내어 읽다", "read aloud"], ["필자", "author"], ["덧붙이다", "add"]], "solution": "정답 (B). 글 2는 책값만이 아니라 ''소리 내어 읽어 주는 모임''처럼 말로 전한 방식도 중요했다고 덧붙입니다. (A)는 ''유일한''이라 틀리고, (C)·(D)는 글 2와 맞지 않습니다.", "strategy": "【두 글 연결】\\n1. 글 1의 주장을 한 줄로 요약하세요.\\n2. 글 2가 그 주장에 대해 무엇을 더하거나 반박하는지 한 줄로 요약하세요.\\n3. ''전부 동의 / 일부 보완 / 전면 부정'' 중 어느 쪽인지 먼저 정합니다.\\n4. 글 2에 없는 지나친 주장(''전혀 영향 없음'', ''유일한 원인'')은 지웁니다.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '이 글에서 설명한 연구 결과는?', '한 연구팀이 철새 30마리에 위치 추적기를 달았다. 철새들은 겨울을 서로 다른 지역에서 보냈지만, 봄이 되자 거의 모두 같은 번식지로 돌아왔다.', 'NONE', '["모든 철새가 같은 곳에서 겨울을 보냈다.", "철새들은 번식지로 돌아오지 않았다.", "겨울을 보낸 곳은 달랐지만 번식지로는 함께 돌아왔다.", "추적기가 철새의 이동 경로를 바꾸었다."]', 'C', 1, '흩어져 겨울을 보냈지만 거의 모두 같은 번식지로 돌아왔다.', 4, '{"translation": "A research team attached tracking devices to 30 migratory birds. The birds spent the winter in different regions, but in spring nearly all of them returned to the same breeding ground.\\n\\nQuestion: Which finding from the study is described in the text?", "vocab": [["연구팀", "research team"], ["철새", "migratory bird"], ["위치 추적기", "tracking device"], ["번식지", "breeding ground"], ["겨울을 보내다", "spend the winter"]], "solution": "정답 (C). ''겨울은 서로 다른 곳에서 보냈다''와 ''거의 모두 같은 번식지로 돌아왔다''를 모두 담은 선택지입니다. (A)·(B)는 글과 반대이고 (D)는 글에 없습니다.", "strategy": "【세부 내용】\\n1. 질문이 묻는 대상(연구 결과, 원인 등)을 글에서 찾아 밑줄을 그으세요.\\n2. 정답은 글의 표현을 바꿔 말한 것입니다. 글과 뜻이 같은지 하나씩 대조하세요.\\n3. 글과 반대되거나 글에 없는 내용을 말하는 선택지는 지웁니다.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '빈칸에 들어갈 연결어로 가장 알맞은 것은?', '보고서는 내용이 명확하다는 평가를 받았다. ______ 몇몇 위원은 예산에 관한 설명이 부족하다고 지적했다.', 'NONE', '["그래서", "마찬가지로", "그러나", "예를 들어"]', 'C', 1, '칭찬 뒤에 비판이 이어지므로 역접의 ''그러나''가 알맞다.', 5, '{"translation": "The report was praised for being clear. ______ several members pointed out that it lacked explanation of the budget.\\n\\nQuestion: Which choice completes the text with the most logical transition?", "vocab": [["연결어", "transition"], ["보고서", "report"], ["평가를 받다", "be praised / be rated"], ["위원", "committee member"], ["지적하다", "point out"], ["그러나", "however"]], "solution": "정답 (C) 그러나. 앞은 칭찬, 뒤는 부족한 점의 지적이므로 대조(역접)입니다. 결과(그래서), 유사(마찬가지로), 예시(예를 들어)는 맞지 않습니다.", "strategy": "【연결어】\\n1. 빈칸 앞 문장과 뒤 문장의 관계를 한 단어로 정하세요: 대조 / 결과 / 유사 / 예시.\\n2. 앞은 칭찬(긍정), 뒤는 지적(부정)처럼 방향이 바뀌는지 보세요.\\n3. 정한 관계에 맞는 연결어를 고르고 넣어 읽어 확인합니다.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '이 글의 역할로 가장 알맞은 것은?', '여러 종류의 꽃이 있는 곳에서 지낸 벌 무리는 한 가지 작물만 먹은 벌 무리보다 꿀을 더 많이 만들었고 병에 걸린 흔적도 적었다.', 'NONE', '["꽃의 다양성과 벌 무리의 건강 사이의 관계를 보고한다.", "꿀 생산량이 줄고 있다고 주장한다.", "벌이 한 가지 작물을 고르는 방법을 설명한다.", "벌의 병을 치료하는 방법을 소개한다."]', 'A', 1, '꽃의 다양성과 꿀·건강의 관계를 보고하는 글이다.', 6, '{"translation": "Bee colonies that lived where many kinds of flowers grew made more honey and showed fewer signs of disease than colonies that ate only one crop.\\n\\nQuestion: Which choice best describes the function of the text?", "vocab": [["글의 역할", "function of the text"], ["벌 무리", "bee colony"], ["꽃의 다양성", "flower variety"], ["병에 걸린 흔적", "signs of disease"], ["보고하다", "report"]], "solution": "정답 (A). 글은 꽃이 다양한 곳의 벌 무리가 꿀이 많고 병이 적었다는 결과를 보고합니다. 주장(B)이나 방법 설명(C·D)은 없습니다.", "strategy": "【글의 역할·목적】\\n1. 글이 무엇을 ''하는지'' 동사로 정리하세요: 보고한다 / 주장한다 / 설명한다 / 소개한다.\\n2. 연구 결과를 전달하기만 하는지, 자기 주장을 펴는지 구분합니다.\\n3. 글의 내용 범위를 벗어난 선택지(감소 주장, 치료 방법 등)는 지웁니다.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '빈칸에 들어갈 말로 가장 알맞은 것은?', '옛 지도는 직접 측량하기보다 뱃사람들의 이야기를 바탕으로 그려졌다. 그래서 큰 항구 근처의 해안선은 정확했지만, 먼 지역으로 갈수록 해안선이 ______.', 'NONE', '["정확해졌다", "왜곡되었다", "붐볐다", "화려해졌다"]', 'B', 1, '정보가 적은 먼 곳일수록 해안선이 왜곡되었다.', 7, '{"translation": "Old maps were drawn from sailors'' stories rather than direct measurement. So coastlines near large ports were accurate, but farther away the coastlines ______.\\n\\nQuestion: Which choice completes the text with the most logical and precise word?", "vocab": [["측량하다", "measure / survey"], ["뱃사람(선원)", "sailor"], ["해안선", "coastline"], ["항구", "port"], ["왜곡되다", "be distorted"]], "solution": "정답 (B) 왜곡되었다. ''항구 근처는 정확했지만(but) 먼 지역으로 갈수록''이라는 대비이므로 ''정확하다''의 반대가 들어갑니다. 정보가 적은 먼 곳일수록 모양이 왜곡된 것입니다.", "strategy": "【문맥 어휘】\\n1. 빈칸을 가린 채 앞뒤 문장만 보고 들어갈 말을 우리말로 먼저 떠올리세요.\\n2. ''once … but later'', '':'' 같은 대비·설명 신호를 찾아 빈칸 방향(긍정/부정, 반대/같음)을 정합니다.\\n3. 떠올린 말과 가장 가까운 선택지를 고르고, 반대 방향 선택지부터 지우세요.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '이 글은 소설을 어떻게 평가하는가?', '이 소설의 줄거리는 단순하지만, 믿기 어려운 화자가 장면마다 말을 바꾸어 독자가 모든 사건을 의심하게 만든다.', 'NONE', '["줄거리가 너무 복잡하다.", "화자 때문에 단순한 이야기가 복잡하게 느껴진다.", "기억에 남는 장면이 없다.", "처음부터 퍼즐 책으로 쓰였다."]', 'B', 1, '믿기 어려운 화자가 단순한 이야기를 수수께끼처럼 만든다.', 8, '{"translation": "The plot of this novel is simple, but an unreliable narrator changes his account in every scene, making readers doubt every event.\\n\\nQuestion: How does the text evaluate the novel?", "vocab": [["줄거리", "plot"], ["믿기 어려운 화자", "unreliable narrator"], ["장면", "scene"], ["의심하다", "doubt / question"], ["평가하다", "evaluate / characterize"]], "solution": "정답 (B). ''줄거리는 단순하지만(but) 화자 때문에 모든 사건을 의심하게 된다''에서 강조점은 뒤쪽입니다. (A)는 ''단순하다''와 반대, (C)·(D)는 글에 없습니다.", "strategy": "【글쓴이의 평가】\\n1. 평가 대상(소설)에 대해 글이 쓴 형용사·표현을 모두 표시하세요.\\n2. ''Although A, B'' 구조에서는 B가 글쓴이가 강조하는 내용입니다.\\n3. 표현을 그대로 옮기지 않았더라도 같은 뜻인 선택지를 고르세요.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '빈칸에 들어갈 말로 가장 알맞은 것은?', '그 기술자의 제안은 ______: 위원회가 제기한 모든 우려를 다루면서도 처음 예산을 넘지 않았다.', 'NONE', '["포괄적이었다", "잠정적이었다", "사치스러웠다", "모호했다"]', 'A', 1, '모든 우려를 다루었으므로 ''포괄적''이다.', 9, '{"translation": "The engineer''s proposal was ______: it addressed every concern the committee had raised while staying within the original budget.\\n\\nQuestion: Which choice completes the text with the most logical and precise word?", "vocab": [["기술자", "engineer"], ["제안", "proposal"], ["우려를 다루다", "address a concern"], ["예산", "budget"], ["포괄적인", "comprehensive"]], "solution": "정답 (A) 포괄적이었다. 콜론 뒤의 ''모든 우려를 다루었다''가 빠짐없다는 뜻의 ''포괄적''을 뒷받침합니다. ''예산 안에서''와 (C) 사치스러운은 반대이고, (B)·(D)는 근거가 없습니다.", "strategy": "【문맥 어휘】\\n1. 빈칸을 가린 채 앞뒤 문장만 보고 들어갈 말을 우리말로 먼저 떠올리세요.\\n2. ''once … but later'', '':'' 같은 대비·설명 신호를 찾아 빈칸 방향(긍정/부정, 반대/같음)을 정합니다.\\n3. 떠올린 말과 가장 가까운 선택지를 고르고, 반대 방향 선택지부터 지우세요.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'RW', 'SAT_RW_MC', '글에 따르면 숲이 줄어든 원인은?', '호수 퇴적물 속 꽃가루를 조사한 결과, 이 지역의 숲은 마지막 빙하기 이후 빠르게 넓어졌다가 초기 농민들이 땅을 개간하면서 다시 줄어들었다.', 'NONE', '["추운 날씨가 돌아와서", "호수의 수위가 변해서", "초기 농민들이 땅을 개간해서", "병으로 나무가 죽어서"]', 'C', 1, '농민의 개간이 원인으로 제시된다.', 10, '{"translation": "Research on pollen in lake sediments showed that forests in this region spread quickly after the last ice age and then shrank again as early farmers cleared the land.\\n\\nQuestion: According to the text, what caused the forests to shrink?", "vocab": [["퇴적물", "sediment"], ["꽃가루", "pollen"], ["빙하기", "ice age"], ["개간하다", "clear land"], ["원인", "cause"]], "solution": "정답 (C). ''초기 농민들이 땅을 개간하면서 다시 줄어들었다''에서 원인이 바로 나옵니다. (A)·(B)·(D)는 글에 없습니다.", "strategy": "【원인 찾기】\\n1. 질문의 결과(숲이 줄어듦)가 글의 어디에 나오는지 찾으세요.\\n2. 그 바로 앞뒤의 ''as'', ''because'', ''after'' 같은 원인 표현을 확인합니다.\\n3. 글에 나오지 않은 원인(날씨, 질병)은 그럴듯해도 지웁니다.", "translationTitle": "영어 원문"}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_MC', '3x + 7 = 22일 때, x의 값은?', NULL, 'NONE', '["3", "5", "7", "15"]', 'B', 1, '양변에서 7을 빼면 3x = 15, 3으로 나누면 x = 5.', 11, '{"translation": "If 3x + 7 = 22, what is the value of x?", "translationTitle": "영어 원문", "vocab": [["값", "value"], ["방정식", "equation"]], "solution": "정답 (B) 5. 양변에서 7을 빼면 3x = 15, 3으로 나누면 x = 5입니다. 확인: 3(5) + 7 = 22.", "strategy": "【일차방정식】\\n1. 숫자 항을 반대편으로 옮기고(덧셈↔뺄셈), x의 계수로 나누세요.\\n2. 구한 값을 원래 식에 넣어 확인하면 부호 실수를 막을 수 있습니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_MC', '점 (0, 2)와 (4, 10)을 지나는 직선의 기울기는?', NULL, 'NONE', '["1/2", "2", "4", "8"]', 'B', 1, '(10 − 2) / (4 − 0) = 8 / 4 = 2.', 12, '{"translation": "A line passes through (0, 2) and (4, 10). What is its slope?", "translationTitle": "영어 원문", "vocab": [["직선", "line"], ["~을 지나다", "pass through"], ["기울기", "slope"]], "solution": "정답 (B) 2. 기울기 = (10 − 2) ÷ (4 − 0) = 8 ÷ 4 = 2입니다. (A) 1/2은 분자·분모를 뒤집은 값입니다.", "strategy": "【기울기】\\n1. 기울기 = (y의 변화량) ÷ (x의 변화량)입니다.\\n2. 두 점의 순서를 분자와 분모에서 똑같이 맞추세요.\\n3. 1/2처럼 분자·분모를 뒤집은 선택지가 흔한 함정입니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_SPR', '가로 12, 세로 5인 직사각형의 대각선 길이는?', NULL, 'NONE', NULL, '13', 1, '√(12² + 5²) = √169 = 13.', 13, '{"translation": "A rectangle has a length of 12 and a width of 5. What is the length of its diagonal?", "translationTitle": "영어 원문", "vocab": [["직사각형", "rectangle"], ["가로(길이) / 세로(폭)", "length / width"], ["대각선", "diagonal"]], "solution": "정답 13. 대각선² = 12² + 5² = 144 + 25 = 169이므로 대각선 = 13입니다.", "strategy": "【피타고라스 정리 · 직접 입력】\\n1. 직사각형의 대각선은 가로·세로를 두 변으로 하는 직각삼각형의 빗변입니다.\\n2. 공식표의 c² = a² + b²를 쓰세요. 5, 12, 13처럼 자주 나오는 세 수를 기억해 두면 빠릅니다.\\n3. 답은 숫자만 입력합니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_SPR', '7/4를 소수 또는 분수로 나타내면?', NULL, 'NONE', NULL, '1.75|7/4', 1, '7 ÷ 4 = 1.75.', 14, '{"translation": "What is the value of 7/4 written as a decimal or fraction?", "translationTitle": "영어 원문", "vocab": [["소수", "decimal"], ["분수", "fraction"], ["~로 나타낸", "written as"]], "solution": "정답 1.75 (또는 7/4). 7 ÷ 4 = 1.75입니다. 두 꼴 모두 정답입니다.", "strategy": "【분수 ↔ 소수 · 직접 입력】\\n1. 분수는 분자 ÷ 분모로 소수가 됩니다.\\n2. 이 문항은 분수 그대로 넣어도, 소수로 넣어도 정답입니다.\\n3. 대분수(1 3/4)는 입력할 수 없습니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_MC', '80의 15%는?', NULL, 'NONE', '["8", "10", "12", "15"]', 'C', 1, '0.15 × 80 = 12.', 15, '{"translation": "What is 15% of 80?", "translationTitle": "영어 원문", "vocab": [["퍼센트", "percent (%)"], ["~의", "of"]], "solution": "정답 (C) 12. 80 × 0.15 = 12입니다(10%는 8, 5%는 4, 합 12).", "strategy": "【백분율】\\n1. a%는 a/100입니다. ''80의 15%''는 80 × 0.15입니다.\\n2. 10%(8)와 5%(4)로 나눠 더하면 암산이 쉽습니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_MC', '(x + 3)(x − 3)과 같은 식은?', NULL, 'NONE', '["x² − 9", "x² + 9", "x² − 6x + 9", "x² + 6x − 9"]', 'A', 1, '합차 공식: x² − 3².', 16, '{"translation": "Which expression is equivalent to (x + 3)(x − 3)?", "translationTitle": "영어 원문", "vocab": [["식", "expression"], ["~과 같은(동치인)", "equivalent to"]], "solution": "정답 (A) x² − 9. 합차 공식 (a + b)(a − b) = a² − b²에 따라 x² − 3² = x² − 9입니다.", "strategy": "【합차 공식】\\n1. (a + b)(a − b) = a² − b²를 떠올리세요.\\n2. 가운데 항(±6x)이 생기는 것은 (x ± 3)²처럼 같은 부호를 곱할 때뿐입니다.\\n3. 헷갈리면 x = 1을 넣어 원래 식과 선택지 값을 비교하세요."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_SPR', 'f(x) = 2x² − 1일 때, f(3)의 값은?', NULL, 'NONE', NULL, '17', 1, '2 · 9 − 1 = 17.', 17, '{"translation": "If f(x) = 2x² − 1, what is f(3)?", "translationTitle": "영어 원문", "vocab": [["함수", "function"], ["x = 3일 때의 함숫값", "f(3)"]], "solution": "정답 17. f(3) = 2 × 3² − 1 = 2 × 9 − 1 = 17입니다.", "strategy": "【함숫값 · 직접 입력】\\n1. f(3)은 x 자리에 3을 넣으라는 뜻입니다.\\n2. 거듭제곱을 먼저 계산하고(3² = 9) 곱셈, 뺄셈 순서로 계산하세요."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_MC', '연립방정식 y = 2x + 1, y = −x + 7의 해 (x, y)에서 x의 값은?', NULL, 'NONE', '["1", "2", "3", "5"]', 'B', 1, '2x + 1 = −x + 7에서 3x = 6, x = 2.', 18, '{"translation": "The system y = 2x + 1 and y = −x + 7 has one solution (x, y). What is x?", "translationTitle": "영어 원문", "vocab": [["연립방정식", "system (of equations)"], ["해", "solution"]], "solution": "정답 (B) 2. 2x + 1 = −x + 7에서 3x = 6, x = 2입니다(이때 y = 5).", "strategy": "【연립방정식】\\n1. 두 식이 모두 y = … 꼴이면 오른쪽끼리 같다고 놓으세요.\\n2. x를 구한 뒤 묻는 것이 x인지 y인지 다시 확인하세요.\\n3. 계산기 그래프에 두 식을 넣고 만나는 점을 봐도 됩니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_SPR', '원의 방정식이 (x − 2)² + (y + 1)² = 49일 때, 반지름은?', NULL, 'NONE', NULL, '7', 1, '우변이 r²이므로 r = 7.', 19, '{"translation": "A circle has the equation (x − 2)² + (y + 1)² = 49. What is its radius?", "translationTitle": "영어 원문", "vocab": [["원", "circle"], ["반지름", "radius"], ["중심", "center"]], "solution": "정답 7. 오른쪽 49가 r²이므로 r = 7입니다. 중심은 (2, −1)입니다.", "strategy": "【원의 방정식 · 직접 입력】\\n1. (x − a)² + (y − b)² = r²에서 중심은 (a, b), 반지름은 r입니다.\\n2. 오른쪽 수는 r²이므로 제곱근을 구해야 합니다. 그 수를 그대로 답으로 쓰는 실수가 흔합니다."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_MC', '2^{x+1} = 32일 때, x의 값은?', NULL, 'NONE', '["3", "4", "5", "6"]', 'B', 1, '32 = 2⁵이므로 x + 1 = 5, x = 4.', 20, '{"translation": "If 2^{x+1} = 32, what is x?", "translationTitle": "영어 원문", "vocab": [["지수", "exponent"], ["2의 거듭제곱", "power of 2"]], "solution": "정답 (B) 4. 32 = 2⁵이므로 x + 1 = 5, x = 4입니다. (C) 5는 x + 1의 값입니다.", "strategy": "【지수 방정식】\\n1. 양변을 같은 밑(2)의 거듭제곱으로 바꾸세요.\\n2. 밑이 같으면 지수끼리 같다고 놓고 풉니다.\\n3. 지수 자리의 식(x + 1)을 x로 착각하지 마세요."}'),
(@sat_ko01_exam_id, 'MATH', 'SAT_MATH_SPR', '다섯 수의 평균이 12이고 그중 네 수가 10, 11, 13, 14일 때, 나머지 한 수는?', NULL, 'NONE', NULL, '12', 1, '합은 60이고 60 − 48 = 12.', 21, '{"translation": "The mean of five numbers is 12. Four of them are 10, 11, 13 and 14. What is the fifth?", "translationTitle": "영어 원문", "vocab": [["평균", "mean"], ["다섯째 수", "the fifth (number)"]], "solution": "정답 12. 전체 합 = 12 × 5 = 60, 네 수의 합 = 48이므로 60 − 48 = 12입니다.", "strategy": "【평균 · 직접 입력】\\n1. 평균 × 개수 = 전체 합입니다.\\n2. 전체 합에서 아는 수들의 합을 빼면 나머지 수가 나옵니다."}');
